/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const servers = [];

  function scan(host, parent) {
    if (visited.has(host)) return;
    visited.add(host);
    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (neighbor === parent) continue;
      scan(neighbor, host);
    }
    if (host !== 'home') servers.push(host);
  }

  scan('home', '');

  const hackLvl = ns.getHackingLevel();
  ns.tprint(`=== SERVER SURVEY (Hack Level: ${hackLvl}) ===`);
  ns.tprint(`${'HOST'.padEnd(24)} ${'REQ'.padStart(5)} ${'MAX MONEY'.padStart(14)} ${'MIN SEC'.padStart(8)} ${'ROOT'.padStart(5)}`);
  ns.tprint('-'.repeat(62));

  const results = [];
  for (const host of servers) {
    const req = ns.getServerRequiredHackingLevel(host);
    const maxMon = ns.getServerMaxMoney(host);
    const minSec = ns.getServerMinSecurityLevel(host);
    const root = ns.hasRootAccess(host);
    results.push({ host, req, maxMon, minSec, root });
  }

  // Sort by max money descending
  results.sort((a, b) => b.maxMon - a.maxMon);

  for (const r of results) {
    const monStr = ns.format.number(r.maxMon, '0.000a');
    const hackable = r.req <= hackLvl ? '*' : ' ';
    ns.tprint(
      `${hackable}${r.host.padEnd(23)} ${String(r.req).padStart(5)} ${monStr.padStart(14)} ${r.minSec.toFixed(1).padStart(8)} ${String(r.root).padStart(5)}`
    );
  }

  ns.tprint('=== END SURVEY ===');
}

/** @param {NS} ns */
export async function main(ns) {
  // Recursive scan
  function scanAll() {
    const visited = new Set(['home']);
    const queue = ['home'];
    while (queue.length) {
      const cur = queue.pop();
      for (const n of ns.scan(cur)) {
        if (!visited.has(n)) { visited.add(n); queue.push(n); }
      }
    }
    visited.delete('home');
    return [...visited];
  }

  // Try to gain root on a server
  function tryNuke(host) {
    if (ns.hasRootAccess(host)) return true;
    let ports = 0;
    try { ns.brutessh(host); ports++; } catch(_) {}
    try { ns.ftpcrack(host); ports++; } catch(_) {}
    try { ns.relaysmtp(host); ports++; } catch(_) {}
    try { ns.httpworm(host); ports++; } catch(_) {}
    try { ns.sqlinject(host); ports++; } catch(_) {}
    try { ns.nuke(host); return true; } catch(_) { return false; }
  }

  // Pick best target
  function bestTarget(servers) {
    const hl = ns.getHackingLevel();
    const rooted = servers.filter(s => ns.hasRootAccess(s));
    const preferred = rooted.filter(s => ns.getServerRequiredHackingLevel(s) <= hl / 2);
    const pool = preferred.length ? preferred : rooted;
    if (!pool.length) return null;
    return pool.reduce((best, s) => {
      const m = ns.getServerMaxMoney(s);
      return m > ns.getServerMaxMoney(best) ? s : best;
    }, pool[0]);
  }

  const servers = scanAll();
  for (const s of servers) tryNuke(s);

  let target = bestTarget(servers);
  if (!target) { ns.tprint('No valid target found'); return; }
  ns.tprint(`Target: ${target}, money: $${ns.getServerMoneyAvailable(target)}`);

  let iter = 0;
  while (true) {
    if (iter % 20 === 0) {
      for (const s of servers) tryNuke(s);
      const newTarget = bestTarget(servers);
      if (newTarget && newTarget !== target) {
        target = newTarget;
        ns.tprint(`New target: ${target}`);
      }
    }
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);
    if (iter % 5 === 0) ns.print(`[${iter}] ${target} sec:${sec.toFixed(1)}/${minSec} money:${money}/${maxMoney}`);
    if (sec > minSec + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
    iter++;
  }
}

/** @param {NS} ns */
export async function main(ns) {
  // Hardcoded minimal version targeting n00dles
  const target = 'n00dles';

  // Try to get root access
  try { ns.nuke(target); } catch(e) {}

  if (!ns.hasRootAccess(target)) {
    ns.tprint('ERROR: No root access on ' + target);
    return;
  }

  ns.tprint('INFO: Starting hack loop on ' + target);

  let iter = 0;
  while (true) {
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);

    if (sec > minSec + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
    iter++;
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const host = 'n00dles';
  try { ns.nuke(host); } catch(e) {}
  const sec = ns.getServerSecurityLevel(host);
  const money = ns.getServerMoneyAvailable(host);
  const minSec = 1;
  const maxMoney = 1750000;
  let action;
  if (sec > minSec + 3) {
    action = 'weaken';
    await ns.weaken(host);
  } else if (money < maxMoney * 0.9) {
    action = 'grow';
    await ns.grow(host);
  } else {
    action = 'hack';
    await ns.hack(host);
  }
  ns.tprint('done action=' + action + ' sec=' + sec + ' money=' + money);
}

